-- PubHTML5의 '한식메뉴' 목차를 참고해 가정용 분량과 간단한 설명으로 재구성한 한식 14종입니다.
insert into public.recipes (title, summary, cook_minutes, difficulty, instructions, tags) values
('국물 떡볶이','떡과 어묵을 매콤달콤한 양념에 끓이는 국민 간식',20,'쉬움','["물에 고추장과 간장을 풀어 끓입니다.","떡과 어묵, 양파를 넣고 중불에서 익힙니다.","국물이 걸쭉해지면 대파를 넣어 마무리합니다."]',array['한식','분식','매콤']),
('닭 한마리 삼계탕','닭과 대추, 마늘을 푹 끓여 만드는 보양식',70,'보통','["닭을 깨끗이 손질하고 한 번 데칩니다.","냄비에 닭과 마늘, 대추를 넣고 충분히 끓입니다.","소금과 대파를 곁들여 간을 맞춥니다."]',array['한식','국','닭고기']),
('돼지고기 김치찌개','잘 익은 김치와 돼지고기로 깊게 끓이는 찌개',30,'쉬움','["돼지고기와 김치를 냄비에서 볶습니다.","물을 붓고 고춧가루와 국간장을 넣어 끓입니다.","두부와 대파를 넣고 한소끔 더 끓입니다."]',array['한식','찌개','김치']),
('해물짬뽕','오징어와 새우, 채소를 얼큰하게 끓인 면 요리',30,'보통','["대파와 마늘, 고춧가루를 기름에 볶습니다.","채소와 해물을 넣고 센 불에서 볶다가 물을 붓습니다.","간을 맞춘 국물을 삶은 면에 부어 냅니다."]',array['한식','면','해물','매콤']),
('제육볶음','돼지고기와 양파를 고추장 양념에 볶는 밥도둑',25,'쉬움','["고추장과 간장, 고춧가루로 양념을 만듭니다.","돼지고기를 양념에 버무려 팬에서 볶습니다.","양파와 대파를 넣고 센 불에서 마무리합니다."]',array['한식','볶음','돼지고기']),
('마파두부','두부와 다진 돼지고기를 매콤한 소스에 볶는 한 그릇',25,'보통','["마늘과 다진 돼지고기를 볶습니다.","고추장과 된장, 물을 넣어 소스를 만듭니다.","두부를 넣고 부서지지 않게 조려 대파를 올립니다."]',array['한식','두부','돼지고기']),
('채소 비빔밥','여러 채소와 달걀을 고추장에 비벼 먹는 한 그릇',30,'보통','["콩나물과 시금치는 데쳐 가볍게 무칩니다.","당근과 버섯은 각각 볶고 달걀프라이를 만듭니다.","밥 위에 재료를 올려 고추장과 참기름을 곁들입니다."]',array['한식','한그릇','채소']),
('매콤 쫄면','쫄깃한 면과 아삭한 채소를 새콤한 양념에 비비는 요리',18,'쉬움','["고추장과 식초, 설탕으로 양념장을 만듭니다.","쫄면을 삶아 찬물에 충분히 헹굽니다.","양배추와 오이를 넣고 양념장에 고루 비빕니다."]',array['한식','면','매콤']),
('돼지고기 김치찜','김치와 돼지고기를 부드러워질 때까지 푹 익힌 요리',50,'보통','["냄비에 김치와 돼지고기를 차례로 담습니다.","고춧가루와 간장, 물을 넣고 뚜껑을 덮어 끓입니다.","김치가 부드러워지면 대파를 넣고 마무리합니다."]',array['한식','찜','김치','돼지고기']),
('매운 닭발볶음','삶은 닭발을 매콤한 양념에 졸이듯 볶는 야식',45,'보통','["닭발을 삶아 깨끗이 헹굽니다.","고추장과 고춧가루, 간장으로 양념을 만듭니다.","닭발과 양념을 팬에서 충분히 볶아 깨를 뿌립니다."]',array['한식','야식','매콤']),
('간장치킨','바삭한 닭고기에 달콤짭짤한 간장 소스를 입힌 요리',40,'보통','["닭고기에 소금과 후추로 밑간합니다.","전분을 묻혀 노릇하고 바삭하게 익힙니다.","간장과 올리고당을 끓인 소스에 빠르게 버무립니다."]',array['한식','닭고기','간식']),
('고추장 양념치킨','바삭한 닭고기를 매콤달콤한 고추장 소스에 버무린 요리',40,'보통','["닭고기에 밑간하고 전분을 얇게 묻힙니다.","팬이나 에어프라이어에서 바삭하게 익힙니다.","고추장과 케첩, 올리고당을 끓인 소스에 버무립니다."]',array['한식','닭고기','매콤']),
('참치 주먹밥','참치마요를 넣어 한입 크기로 빚는 간단한 밥 요리',15,'쉬움','["참치의 기름을 빼고 마요네즈와 섞습니다.","밥에 참기름과 김가루를 넣어 섞습니다.","밥 속에 참치를 넣고 단단하게 뭉칩니다."]',array['한식','한그릇','참치']),
('견과류 멸치볶음','잔멸치와 견과류를 달콤짭짤하게 볶는 밑반찬',15,'쉬움','["마른 팬에서 멸치와 견과류를 각각 볶습니다.","간장과 올리고당을 약불에서 끓입니다.","멸치와 견과류를 넣어 빠르게 섞고 깨를 뿌립니다."]',array['한식','반찬','멸치'])
on conflict do nothing;

insert into public.recipe_ingredients (recipe_id, ingredient_name, amount, is_optional, sort_order)
select r.id, v.ingredient_name, v.amount, v.is_optional, v.sort_order
from public.recipes r
join (values
('국물 떡볶이','떡볶이떡','300g',false,1),('국물 떡볶이','어묵','3장',false,2),('국물 떡볶이','고추장','2큰술',false,3),('국물 떡볶이','대파','조금',true,4),
('닭 한마리 삼계탕','닭','1마리',false,1),('닭 한마리 삼계탕','마늘','6쪽',false,2),('닭 한마리 삼계탕','대추','4개',true,3),
('돼지고기 김치찌개','돼지고기','200g',false,1),('돼지고기 김치찌개','김치','한 줌',false,2),('돼지고기 김치찌개','두부','1/2모',true,3),
('해물짬뽕','오징어','1마리',false,1),('해물짬뽕','새우','6마리',false,2),('해물짬뽕','양배추','한 줌',false,3),('해물짬뽕','중화면','1인분',false,4),
('제육볶음','돼지고기','300g',false,1),('제육볶음','양파','1/2개',false,2),('제육볶음','고추장','2큰술',false,3),('제육볶음','대파','조금',true,4),
('마파두부','두부','1모',false,1),('마파두부','다진 돼지고기','150g',false,2),('마파두부','된장','1큰술',false,3),('마파두부','대파','조금',true,4),
('채소 비빔밥','밥','1공기',false,1),('채소 비빔밥','콩나물','한 줌',false,2),('채소 비빔밥','시금치','한 줌',false,3),('채소 비빔밥','달걀','1개',false,4),('채소 비빔밥','당근','조금',true,5),
('매콤 쫄면','쫄면','1인분',false,1),('매콤 쫄면','양배추','한 줌',false,2),('매콤 쫄면','오이','1/3개',true,3),('매콤 쫄면','고추장','1큰술',false,4),
('돼지고기 김치찜','돼지고기','400g',false,1),('돼지고기 김치찜','김치','1/2포기',false,2),('돼지고기 김치찜','대파','조금',true,3),
('매운 닭발볶음','닭발','500g',false,1),('매운 닭발볶음','고추장','2큰술',false,2),('매운 닭발볶음','고춧가루','1큰술',false,3),('매운 닭발볶음','마늘','1큰술',true,4),
('간장치킨','닭고기','500g',false,1),('간장치킨','간장','3큰술',false,2),('간장치킨','전분','1/2컵',false,3),('간장치킨','올리고당','2큰술',false,4),
('고추장 양념치킨','닭고기','500g',false,1),('고추장 양념치킨','고추장','2큰술',false,2),('고추장 양념치킨','케첩','2큰술',false,3),('고추장 양념치킨','전분','1/2컵',false,4),
('참치 주먹밥','밥','1공기',false,1),('참치 주먹밥','참치캔','1개',false,2),('참치 주먹밥','마요네즈','1큰술',false,3),('참치 주먹밥','김가루','한 줌',true,4),
('견과류 멸치볶음','잔멸치','1컵',false,1),('견과류 멸치볶음','견과류','1/2컵',false,2),('견과류 멸치볶음','간장','1큰술',false,3),('견과류 멸치볶음','올리고당','1큰술',false,4)
) as v(recipe_title, ingredient_name, amount, is_optional, sort_order)
  on r.title = v.recipe_title and r.created_by is null
where not exists (
  select 1 from public.recipe_ingredients ri
  where ri.recipe_id = r.id and ri.ingredient_name = v.ingredient_name
);
